  ($str$PM Melting$str$, 2120),
  ($str$PM Molding$str$, 2121),
  ($str$Pour$str$, 2122),
  ($str$Shakeout$str$, 2123),
  ($str$Shell$str$, 2124),
  ($str$Stock Core$str$, 2125),
  ($str$Vertical Automatic$str$, 2126)
) AS v(name, display_order)
  ON pt.process_group = $str$Casting$str$ AND pt.process_name = v.name
WHERE NOT EXISTS (
  SELECT 1 FROM process_calculator_mappings m WHERE m.process_group = $str$Casting$str$ AND m.operation = v.name
)
ON CONFLICT (process_group, process_route, operation) DO NOTHING;

COMMIT;

NOTIFY pgrst, 'reload schema';

